def is_anagram(s: str, t: str) -> bool:
    return len(s) == len(t) and Counter(s) == Counter(t)

def two_sum(nums: list[int], target: int) -> list[int]:
    index = {}
    for i, n in enumerate(nums):
        if target - n in index:
            return [index[target - n], i]
        index[n] = i
    return []

